CREATE TABLE private_note_revision (id UUID PRIMARY KEY DEFAULT uuid_v7(),note_id UUID NOT NULL,vault_id UUID NOT NULL,owner_id UUID NOT NULL,revision BIGINT NOT NULL,encrypted_title TEXT NOT NULL,encrypted_body TEXT NOT NULL,encrypted_properties TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(note_id) REFERENCES private_note(id),FOREIGN KEY(vault_id) REFERENCES private_vault(id),UNIQUE(note_id,revision)); CREATE INDEX idx_private_note_revision ON private_note_revision(note_id,revision DESC);
